<section class="container profile-page-hero"><div><p class="eyebrow"><?=e($row['body']['eyebrow']??'')?></p><h1><?=nl2br(e($row['title']))?></h1><p class="large-copy"><?=e($row['summary'])?></p><p class="file-meta" dir="ltr">PDF · <?=number_format(media_size(profile_display_id())/1000000,1)?> MB</p><div class="button-row"><a class="button" href="<?=e(media_url(profile_display_id()))?>" download><?=t('تحميل الملف التعريفي','Download company profile')?> ↓</a><a class="text-link" href="#pdf-preview"><?=t('معاينة الملف','Preview the PDF')?> ↓</a></div></div><?php page_slider($row,'pages','profile','profile');?></section>
